from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=2)
def compare(x_i, x_i_plus_1):
    if x_i > x_i_plus_1:
        return x_i_plus_1, x_i
    return x_i, x_i_plus_1

@task(returns=1)
def rank(x_sorted, value):
    return x_sorted.index(value)


def main(x):
    n = len(x)

    unsorted_x = x.copy()

    for phase in range(n):
        if phase % 2 == 0:
            indices = range(0, n-1, 2)
        else:
            indices = range(1, n-1, 2)

        for i in indices:
            x[i], x[i + 1] = compare(x[i], x[i + 1])

    x = compss_wait_on(x)
    ranks = [None] * n

    for i in range(n):
        ranks[i] = rank(x, unsorted_x[i])

    ranks = compss_wait_on(ranks)

    return ranks
